function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function Evidence({items,onShow}:{items:CoachingEvidence[];onShow?:(squares:string[])=>void}){return <div className="evidence">{items.map((e,i)=><div key={i}><span className={`tag ${e.kind}`}>{e.kind==='principle'?'Planning idea':e.kind==='calculated'?'Engine line':'Board fact'}</span><p>{e.text}</p>{e.squares?.length&&onShow?<button className="show-squares" onClick={()=>onShow(e.squares!)}>◎ Show on board</button>:null}</div>)}</div>;}
