  if(!explore?.originalMove)return;const study=explore,first=branchOf(study).moves[0];if(!first||first===study.originalMove)return;
  cancelSearch();setDecisionAnalysis(null);const token=generation.current,fen=replay(study.root).fen();setBusy(true);
  try{const lines:CandidateLine[]=[];for(const choice of [study.originalMove!,first]){const a=await engine.analyze(fen,1000,1,20,[choice],study.root);if(token!==generation.current)return;const line=a.lines.find(l=>l.move===choice);if(!line)throw new Error('No comparison line returned. Restart the engine and compare again.');lines.push(line);}setDecisionAnalysis({key:decisionKey(study),analysis:{fen,lines,elapsed:2000}});}
