 function recordPractice(id:string,correct:boolean,exerciseId?:string,moment?:LearningMoment){setData(d=>{const previous=d.practice.find(p=>p.id===id)??{id,exerciseId,moment,stage:0,due:new Date().toISOString(),lastSession:'',missed:false,attempts:0};const updated=schedule(previous,correct,practiceSession);return {...d,practice:[...d.practice.filter(p=>p.id!==id),updated]};});}
 async function move(uci:string,base?:GameSession){
  if(!loaded)return;
  if(explore&&!base){try{setAutoPlay(false);setExplore(playInStudy(explore,uci));}catch(e){setError((e as Error).message);}return;}
  cancelSearch();
  if(base){setAutoPlay(false);setData(d=>({...d,activeExplorationId:null}));}
  if(exercise&&!base){if(answer)return;let san;try{san=uciMove(new Chess(exercise.fen),uci).san;}catch{return;}const correct=exercise.accepted.includes(san);setAnswer({uci,correct});setHint(0);setAnalysis(null);recordPractice(exercise.id,correct,exercise.id.startsWith('moment:')?undefined:exercise.id,data.practice.find(p=>p.id===exercise.id)?.moment);return;}
  const session=base??data.current,board=replay(session);
  if(board.isGameOver()||session.pending||session.archived||board.turn()!==session.player)return;
  const before=board.fen(),token=generation.current,c=new Chess(before);let made;try{made=uciMove(c,uci);}catch{return;}
  if(data.settings.coach.pauseAfterMove===false){setFeedback(null);setCoachMode('default');updateGame(()=>({...session,moves:[...session.moves,uci],updated:new Date().toISOString(),pending:false}));return;}
  const evidence=explainMove(before,uci);setFeedback({title:'Let’s look at your move',text:evidence[0].text,evidence});setExpanded(false);setHint(0);setAnalysis(null);
  updateGame(()=>({...session,moves:[...session.moves,uci],updated:new Date().toISOString(),pending:true}));setBusy(true);setError('');
  try{
   const a=await engine.analyze(before,1000,3,20,undefined,session);const best=a.lines[0];
   if(token!==generation.current)return;
   if(best){let played=a.lines.find(l=>l.move===uci);if(!played)played=(await engine.analyze(before,1000,1,20,[uci],session)).lines[0];if(token!==generation.current)return;
    const loss=Math.max(0,score(best)-score(played));const text=best.move===uci?'Your move matches the engine’s leading choice at this search depth.':loss<50?'Your move is close to the engine’s leading choice at this search depth.':`The engine prefers ${sanFor(before,best.move)}. Compare the replies to see what your move allowed.`;
    const moment:LearningMoment={id:crypto.randomUUID(),fen:before,played:uci,best:best.move,loss,explanation:text,pv:best.pv.slice(0,20),position:{initialFen:session.initialFen,moves:[...session.moves]},bestLine:best,playedLine:played};
    setFeedback({title:loss>=150?'A useful moment to revisit':'The idea behind your move',text,evidence:[...evidence,{kind:'calculated',text:played?`After ${made.san}, one possible line is ${lineSan(before,played.pv).join(' ')}. Search depth ${played.depth}; this is not a guaranteed prediction.`:'No stable continuation was returned.'}],moment});
    updateGame(g=>({...g,moments:[...g.moments,moment]}));
   }
  }catch(e){if(token===generation.current&&(e as Error).name!=='AbortError')setError((e as Error).message);}finally{if(token===generation.current)setBusy(false);}
 }
 useEffect(()=>{
  if(!loaded||tab!=='play'||exercise||data.activeExplorationId||data.current.pending||data.current.archived||gameOver||game.turn()===data.current.player)return;
  const key=`${data.current.id}:${data.current.moves.join(',')}`;if(botKey.current===key)return;botKey.current=key;
  const token=generation.current;setBusy(true);
  engine.analyze(game.fen(),650,1,{Gentle:0,Steady:5,Challenging:12}[data.current.difficulty],undefined,data.current).then(a=>{
   if(token!==generation.current)return;if(!a.bestmove)throw new Error('Engine returned no legal reply. Restart it to try again.');uciMove(new Chess(game.fen()),a.bestmove);
   updateGame(g=>({...g,moves:[...g.moves,a.bestmove!],updated:new Date().toISOString()}));setAnalysis(null);setFeedback(null);setHint(0);setCoachMode('default');
  }).catch(e=>{if(token===generation.current&&(e as Error).name!=='AbortError')setError((e as Error).message);}).finally(()=>{if(token===generation.current)setBusy(false);});
 },[loaded,tab,exercise,data.current,gameOver,data.activeExplorationId]);
 useEffect(()=>{if(!loaded||!gameOver||data.current.archived)return;const moments=[...data.current.moments].sort((a,b)=>b.loss-a.loss).slice(0,3);setData(d=>{const practice=moments.reduce((records,m)=>addPractice(records,momentRecord(m)),d.practice);return practice===d.practice?d:{...d,practice};});},[gameOver,data.current.moments,loaded]);
 function undo(){invalidate();setFeedback(null);if(exercise){setAnswer(null);return;}updateGame(g=>{const count=g.pending?1:g.moves.length>=2&&replay(g).turn()===g.player?2:1;const moves=g.moves.slice(0,Math.max(0,g.moves.length-count));const validPositions=new Set<string>();const c=new Chess(g.initialFen);for(const m of moves){validPositions.add(c.fen());uciMove(c,m);}return {...g,moves,pending:false,moments:g.moments.filter(m=>validPositions.has(m.fen)),updated:new Date().toISOString()};});}
 function startExercise(e:LessonExercise){invalidate();setFeedback(null);setExercise(e);setLessonFlipped(new Chess(e.fen).turn()==='b');setAnswer(null);setTab('play');}
 function returnGame(){invalidate();setExercise(null);setAnswer(null);setFeedback(null);setTab('play');}
 function openPractice(r:PracticeRecord){if(r.exerciseId){const e=exercises.find(e=>e.id===r.exerciseId);if(e)startExercise(e);}else if(r.moment){const m=r.moment;startExercise({id:r.id,module:'review',title:'A position from your game',fen:m.fen,accepted:[sanFor(m.fen,m.best)],prompt:'Find the candidate we saved from this position. Compare its consequences with your original move.',hint:explainMove(m.fen,m.best)[0].text,explanation:m.explanation,continuation:lineSan(m.fen,m.pv).slice(1),theme:'tactic'});}}
 function exploreLine(fen:string,pv:string[],label:string){setAutoPlay(false);if(explore&&fen===visibleFen){setExplore(addStudyLine(explore,pv.slice(0,20),label));return;}const c=new Chess(data.current.initialFen),prefix:string[]=[];let matched=c.fen()===fen;for(const m of data.current.moves){if(matched)break;uciMove(c,m);prefix.push(m);matched=c.fen()===fen;}if(matched&&!exercise)beginStudy({initialFen:data.current.initialFen,moves:prefix},pv.slice(0,20),label,{gameId:data.current.id,prefix});else beginStudy({initialFen:fen,moves:[]},pv.slice(0,20),label);}
 function saveMoment(m:LearningMoment){setData(d=>({...d,practice:addPractice(d.practice,momentRecord(m))}));setNotice('Position added to your practice queue (existing positions are kept once).');}
 async function handleFile(file:File){try{if(file.size>10_000_000)throw new Error('Please use a file smaller than 10 MB.');const text=await file.text();if(fileKind==='backup'){const restored=validateBackup(JSON.parse(text));invalidate();setExercise(null);setFeedback(null);setData(restored);setReviewId(null);setTab('play');setLoaded(true);setNotice('Backup restored. Games and practice progress are ready.');}else{const g=importPgn(text);setData(d=>({...d,games:[...d.games,g]}));setNotice('Game imported into your library.');setTab('library');}}catch(e){setError((e as Error).message);}finally{if(fileRef.current)fileRef.current.value='';}}
 function pickFile(kind:'backup'|'pgn'){setFileKind(kind);setTimeout(()=>fileRef.current?.click(),0);}
 function importText(){try{const g=importPgn(pgnText);setData(d=>({...d,games:[...d.games,g]}));setPgnText('');setNotice('Game imported.');}catch(e){setError((e as Error).message);}}

 const history=game.history({verbose:true});const lastOpponentMove=history.slice().reverse().find(m=>m.color!==player);const lastMove=exercise?answer?.uci:data.current.moves.at(-1);
 const review=[...data.current.moments].sort((a,b)=>b.loss-a.loss).slice(0,3);
 const moveDisabled=!loaded||(explore?visible.isGameOver():exercise?!!answer:gameOver||data.current.pending||!!data.current.archived||game.turn()!==player);
 const hintText=exercise&&!answer&&!explore?(hint===1?exercise.prompt:hint===2?exercise.hint:`Try ${exercise.accepted[0]}.`):relevant?.lines[0]?progressiveHint(visibleFen,relevant.lines[0],hint):'';
 const visualHintMove=hint>0?(exercise&&!answer&&!explore?new Chess(exercise.fen).move(exercise.accepted[0]).lan:relevant?.lines[0]?.move):undefined;
